public function execute(InputInterface $input, OutputInterface $output): int
{
    $from = new \DateTimeImmutable((string) $input->getOption('from') ?? '1970-01-01T00:00:00Z');
    $to = new \DateTimeImmutable((string) $input->getOption('to') ?? '2100-01-01T00:00:00Z');

    $rows = $this->rater->report($from, $to);

    $output->writeln('period: ' . $from->format(\DateTimeInterface::ATOM) . ' -> ' . $to->format(\DateTimeInterface::ATOM));
    $output->writeln('user\tmodel\ttokens_input\ttokens_output\ttokens_cache_read\ttokens_cache_write\tcost_usd');

    foreach ($rows as $r) {
        if ($r['user'] === 'TOTAL') {
            continue;
        }
        $output->writeln(sprintf(
            '%s\t%s\t%d\t%d\t%d\t%d\t%s',
            $r['user'], $r['model'],
            $r['tokens_input'], $r['tokens_output'],
            $r['tokens_cache_read'], $r['tokens_cache_write'],
            $r['cost_usd'],
        ));
    }

    $output->writeln(sprintf(
        'Total\t%d\t%d\t%d\t%d\t%s',
        $rows[count($rows)-1]['tokens_input'],
        $rows[count($rows)-1]['tokens_output'],
        $rows[count($rows)-1]['tokens_cache_read'],
        $rows[count($rows)-1]['tokens_cache_write'],
        $rows[count($rows)-1]['cost_usd'],
    ) . (' USD'));

    return 0;
}

