public function execute(InputInterface $input, OutputInterface $output): int
{
    $from = new \DateTimeImmutable((string) $input->getOption('from'));
    $to = new \DateTimeImmutable((string) $input->getOption('to'));

    $rows = $this->rater->report($from, $to);

    $output->writeln('period: ' . $from->format(\DateTimeInterface::ATOM) . ' -> ' . $to->format(\DateTimeInterface::ATOM) . ' UTC (from inclusive, to exclusive)');
    $output->writeln('user\tmodel\ttokens_input\ttokens_output\ttokens_cache_read\ttokens_cache_write\tcost_usd');

    foreach ($rows as $r) {
        $output->writeln(sprintf(
            '%s\t%s\t%d\t%d\t%d\t%d\t%s',
            $r['user'], $r['model'],
            $r['tokens_input'], $r['tokens_output'],
            $r['tokens_cache_read'], $r['tokens_cache_write'],
            $r['cost_usd'],
        ));
    }

    $output->writeln(sprintf('Total\t%d\t%d\t%d\t%d\t%s USD',
        $rows[0]['tokens_input'] + 0,
        $rows[0]['tokens_output'] + 0,
        $rows[0]['tokens_cache_read'] + 0,
        $rows[0]['tokens_cache_write'] + 0,
        $rows[0]['cost_usd'];
    ));

    return 0;
}

